import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"智能合并模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/smart-merge.md","filePath":"zh-Hans/deep-dive/modules/smart-merge.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/modules/smart-merge.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="智能合并模块" tabindex="-1">智能合并模块 <a class="header-anchor" href="#智能合并模块" aria-label="Permalink to “智能合并模块”">​</a></h1><p>智能合并是一个可选的 Markdown 文件文本冲突解决器。它为每个可合并的文件保存一份基础快照，然后用这份快照区分独立编辑与冲突编辑。模块注册一个远端文件系统包装器、<code>smartMerge</code> 冲突解决器和设置。</p><h2 id="支持的文件与注册" tabindex="-1">支持的文件与注册 <a class="header-anchor" href="#支持的文件与注册" aria-label="Permalink to “支持的文件与注册”">​</a></h2><p>去除首尾空格并转小写后以 <code>.md</code> 或 <code>.markdown</code> 结尾的路径才是可合并的。其他文件直接透传，不做基础文本跟踪。</p><p>模块以优先级 <code>20_098</code> 包装远端文件系统。包装器把正常的文件系统行为委托给被包装的实例，并增加基础快照维护。解决器以 ID <code>smartMerge</code> 注册。</p><h2 id="基础快照生命周期" tabindex="-1">基础快照生命周期 <a class="header-anchor" href="#基础快照生命周期" aria-label="Permalink to “基础快照生命周期”">​</a></h2><p>包装器为其本地 / 远端文件系统命名空间接收一个 <code>uni-kv</code> 的 <code>StoreAsync&lt;string&gt;</code>。这个 store 把文件键映射为纯文本快照。</p><ul><li><code>write()</code> 成功后，路径可合并时包装器把写入值存为文本。失败的写入不更新快照。</li><li><code>move()</code> 成功后，已有快照从旧键移到新键。移到相同键不改变 store。</li><li><code>delete()</code> 成功后，该键的快照被删除。</li><li><code>read()</code>、<code>readStream()</code>、<code>mkdir()</code>、<code>stat()</code>、<code>exists()</code> 和 <code>list()</code> 保持原行为。</li></ul><p>数据库 store 名为 <code>base-text-&lt;namespace&gt;</code>，namespace 与插件核心为本地和远端文件系统选择的命名空间相同。这防止快照在不相关的同步目标之间共享。</p><h2 id="冲突解决流程" tabindex="-1">冲突解决流程 <a class="header-anchor" href="#冲突解决流程" aria-label="Permalink to “冲突解决流程”">​</a></h2><p>解决器接收两个 <code>FileStat</code>、文件键、两个文件系统和同步记录存储。它并发读取本地内容、远端内容和存储的基础快照。</p><p>存在基础快照时：</p><ol><li>把本地和远端内容解码为文本。</li><li>两个文本完全相同时，不写入任何一侧；只用现有 UID 刷新同步记录。</li><li>否则合并三个文本：本地为 <code>a</code>，远端为 <code>b</code>，存储快照为 <code>o</code>。</li><li>只把合并后的文本写入当前文本与之不同的那一侧。</li><li>记录得到的本地和远端 UID。</li></ol><p>合并后文件的 <code>mtime</code> 设为 <code>max(local.mtime, remote.mtime)</code>。合并的 <code>meta</code> 把 <code>ctime</code> 保留为两侧最早的创建时间，<code>mtime</code> 设为合并时间，其余元数据字段取两侧的并集。</p><p>没有基础快照时，智能合并无法区分独立变更。它回退到保留最新（latest-survive）行为：把修改时间较新的一侧复制到另一侧。只有 <code>local.mtime &gt; remote.mtime</code> 时本地获胜；时间戳相等选择远端侧。回退使用 SDK 的传输辅助函数，大内容可以流式传输。</p><h2 id="合并模型" tabindex="-1">合并模型 <a class="header-anchor" href="#合并模型" aria-label="Permalink to “合并模型”">​</a></h2><p>合并算法是递归的 diff3 合并。它面向文本，不感知 Markdown AST，并在多个粒度上工作：</p><ul><li>文档层级上，它把内容切成非空行，并保留行之间的换行序列。</li><li>以三个反引号、<code>~~~</code> 或 <code>$$</code> 开头的围栏块按代码拆分并逐行比较。它们的开始和结束围栏保留在合并内容中。</li><li>正文按单词和标点切分，空白保留在 token 之间的接缝处。对通常不带空格书写的文字，它使用 <code>Intl.Segmenter</code> 并自动检测日语、中文、泰语、老挝语、高棉语、缅甸语和藏语文本。</li></ul><p>对每个 diff3 区域，算法应用这些规则：</p><ul><li>本地与远端相等时，保留该值。</li><li>一侧仍等于基础时，保留另一侧的变更。</li><li>两侧以不同方式修改了同一区域时，产生一个冲突。</li><li>冲突区域可以在更细粒度上拆分时，先递归再产生标记。这让同一行或同一代码块内互不相关的编辑可以独立合并。</li></ul><p>组合区域时，空白和换行接缝保留自源区间。算法不尝试对结果文档做语义或语法校验。</p><h2 id="冲突标记" tabindex="-1">冲突标记 <a class="header-anchor" href="#冲突标记" aria-label="Permalink to “冲突标记”">​</a></h2><p>冲突内容直接写入合并后的文件。普通的双侧冲突表示为被 <code>ours</code> 标记包裹的本地内容，后接被 <code>theirs</code> 标记包裹的远端内容。一侧删除内容、另一侧修改时，幸存内容由删除标记包裹。</p><p>默认标记：</p><table tabindex="0"><thead><tr><th>用途</th><th>开始</th><th>结束</th></tr></thead><tbody><tr><td>本地 (<code>ours</code>)</td><td><code>&lt;mark class=&quot;conflict ours&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr><tr><td>远端 (<code>theirs</code>)</td><td><code>&lt;mark class=&quot;conflict theirs&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr><tr><td>删除</td><td><code>&lt;mark class=&quot;conflict deleted&quot;&gt;</code></td><td><code>&lt;/mark&gt;</code></td></tr></tbody></table><p>用户可以在智能合并设置中独立配置全部六个标记字符串。修改会更新模块设置并通过插件设置存储持久化。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};